<?php
require_once __DIR__ . '/portal-bootstrap.php';
$user=portal_user();
if(!$user){header('Location: patient-login.php');exit;}
$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT);
if(!$id){http_response_code(400);exit('Invalid prescription request.');}
$pdo=portal_db();
$q=$pdo->prepare("SELECT p.*,pt.patient_name,pt.phone,d.doctor_name,d.specialization,dep.department_name
 FROM prescriptions p JOIN patient pt ON pt.patient_id=p.patient_id
 JOIN doctor d ON d.doctor_id=p.doctor_id JOIN department dep ON dep.department_id=d.department_id
 WHERE p.prescription_id=? LIMIT 1");
$q->execute([$id]);$rx=$q->fetch();
if(!$rx){http_response_code(404);exit('Prescription not found.');}
$allowed=false;
if($user['role']==='Patient') $allowed=(int)$rx['patient_id']===(int)$user['patient_id'];
elseif($user['role']==='Doctor') $allowed=(int)$rx['doctor_id']===(int)$user['doctor_id'];
elseif(in_array($user['role'],['Admin','LabStaff'],true)) $allowed=true;
if(!$allowed){http_response_code(403);exit('You are not authorized to view this prescription.');}
$itemsQ=$pdo->prepare('SELECT * FROM prescription_items WHERE prescription_id=? ORDER BY item_id');$itemsQ->execute([$id]);$items=$itemsQ->fetchAll();
portal_audit((int)$user['account_id'],'prescription_viewed',(int)$id);
?>
