<div class="meta"><div><b>Prescription ID:</b> <?= (int)$rx['prescription_id'] ?></div><div><b>Date:</b> <?= portal_e($rx['created_at']) ?></div><div><b>Patient:</b> <?= portal_e($rx['patient_name']) ?></div><div><b>Doctor:</b> <?= portal_e($rx['doctor_name']) ?></div><div><b>Department:</b> <?= portal_e($rx['department_name']) ?></div><div><b>Specialization:</b> <?= portal_e($rx['specialization']) ?></div></div>
<h3>Diagnosis</h3><p><?= nl2br(portal_e($rx['diagnosis'])) ?></p>
