<?php foreach($items as $it): ?><tr><td><?= portal_e($it['medicine_name']) ?></td><td><?= portal_e($it['dose']) ?></td><td><?= portal_e($it['frequency']) ?></td><td><?= portal_e($it['duration']) ?></td><td><?= portal_e($it['instructions']) ?></td></tr><?php endforeach; ?>
</tbody></table>
<?php if($rx['clinical_notes']): ?><h3>Clinical Notes</h3><p class="notes"><?= nl2br(portal_e($rx['clinical_notes'])) ?></p><?php endif; ?>
<div class="signature"><p>____________________________</p><b><?= portal_e($rx['doctor_name']) ?></b><br><?= portal_e($rx['specialization']) ?></div>
